package com.rastudio.commerce.organization;
import com.rastudio.commerce.audit.AuditLogService; import com.rastudio.commerce.common.ApiException; import com.rastudio.commerce.security.TenantPrincipal; import jakarta.servlet.http.HttpServletRequest; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/organization") public class OrganizationController { private final OrganizationRepository organizations; private final SystemConfigRepository configs; private final AuditLogService audit; public OrganizationController(OrganizationRepository organizations,SystemConfigRepository configs,AuditLogService audit){this.organizations=organizations;this.configs=configs;this.audit=audit;} @GetMapping public Organization current(@AuthenticationPrincipal TenantPrincipal p){return organizations.findById(p.organizationId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"ORGANIZATION_NOT_FOUND","Organization not found"));} @GetMapping("/config") public SystemConfig config(@AuthenticationPrincipal TenantPrincipal p){return configs.findById(p.organizationId()).orElseGet(()->{var c=new SystemConfig();c.organizationId=p.organizationId();return configs.save(c);});}
 // Phase 3: "Save System Configuration" is now also audit-logged, per the
 // roadmap's "implement audit logging for administrative actions" — this
 // endpoint itself already existed from Phase 0-2, only the audit call and
 // its HttpServletRequest (for ip_address) are new here.
 @PutMapping("/config") public SystemConfig update(@AuthenticationPrincipal TenantPrincipal p,@RequestBody SystemConfig input,HttpServletRequest http){if(p.role()!=com.rastudio.commerce.user.UserRole.BUSINESS_OWNER_ADMIN)throw new ApiException(HttpStatus.FORBIDDEN,"FORBIDDEN","Only an administrator can update configuration"); var c=configs.findById(p.organizationId()).orElseGet(()->{var x=new SystemConfig();x.organizationId=p.organizationId();return x;}); String previous="syncInterval="+c.syncInterval+", currency="+c.currency+", twoFactor="+c.twoFactorEnabled+", emailDigest="+c.emailDigestEnabled; c.syncInterval=input.syncInterval;c.currency=input.currency;c.twoFactorEnabled=input.twoFactorEnabled;c.emailDigestEnabled=input.emailDigestEnabled; var saved=configs.save(c); String updated="syncInterval="+saved.syncInterval+", currency="+saved.currency+", twoFactor="+saved.twoFactorEnabled+", emailDigest="+saved.emailDigestEnabled; audit.record(p.organizationId(),p.userId(),"UPDATE_SYSTEM_CONFIG","system_config",p.organizationId(),previous,updated,http); return saved;} }